window.products.push({"id":646800,"name":"Pacific Coast Feather National Sleep Products Luxury Down Comforter, King","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/31TJ42VGMML._AC_.jpg","description":"Product Description Luxury Down Comforter, King Amazon.com This National Sleep Products down comforter for King beds combines the softness of an elegantly smooth 300-thread-count, 100-percent cotton cover with the fluffiness of natural down for an immensely luxurious and restful sleeping experience. The comforter is filled with natural down with a fill power of 525, making it suitable for average room temperatures and year-round use in most climates. It should be dry-cleaned only for best results. Fill power is the measurement in which an ounce of down will loft and expand to fill an empty space. Down warmth is a function of both fill power and the amount of fill in a comforter. Higher quality down has higher fill power and will loft higher, requiring fewer ounces of down to create insulating warmth.","images":["https://m.media-amazon.com/images/I/31TJ42VGMML._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Pacific Coast Feather","source_asin":"B000BVNTGA","category_path":"Home & Kitchen"},"sku":"BM-646800","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B000BVNTGA","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B000BVNTGA","price_pending":true,"merchant_ready":false});
